      mc('Che cosa significa bandiera gialla?', ['Pericolo: rallentare e nessun sorpasso', 'Fine turno', 'Pista libera', 'Richiamo ai box'], 0, 'La gialla è un avviso di pericolo sulla pista.'),
      mc('Che cosa significa bandiera rossa?', ['Sessione interrotta: rallentare e rientrare ai box', 'Pista libera', 'Pilota più veloce in arrivo', 'Fondo scivoloso'], 0, 'La rossa ferma tutti.'),
      mc('Bandiera blu:', ['Un pilota più veloce sta arrivando: lascia spazio senza manovre brusche', 'Fine turno', 'Sorpasso vietato', 'Pericolo'], 0, 'Si fa passare con prevedibilità.'),
      mc('Dopo una caduta con sospetto trauma al collo:', ['Non muoverti, non togliere il casco, attendi i soccorsi', 'Ti alzi subito', 'Togli il casco per respirare', 'Rimonti in sella'], 0, 'Muoversi o togliere il casco può peggiorare una lesione.'),
      order('Ordina il rientro dopo una caduta', ['Valutazione fisica e visita medica se serve', 'Sostituzione equipaggiamento danneggiato', 'Controllo tecnico della moto', 'Primo turno a ritmo ridotto', 'Aumento graduale del ritmo'], 'Prima salute e sicurezza, poi ritmo ridotto e progressione.')
